-- Additive; historical invoices, payments and documents are not rewritten.
ALTER TABLE invoices ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN issued BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN reconciliation_id VARCHAR(36) NULL, ADD INDEX idx_invoice_due_archive (archived,due_date,status), ADD INDEX idx_invoice_customer_archive (customer_id,archived,id);
CREATE TABLE invoice_presentations (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,header VARCHAR(255) NOT NULL,company VARCHAR(1000) NOT NULL,footer VARCHAR(1000) NOT NULL,mentions VARCHAR(1000) NOT NULL,layout VARCHAR(20) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,used BOOLEAN NOT NULL DEFAULT FALSE,logo LONGBLOB NULL);
CREATE TABLE invoice_documents (invoice_id BIGINT NOT NULL PRIMARY KEY,presentation_id BIGINT NOT NULL,content LONGBLOB NOT NULL,digest VARCHAR(64) NOT NULL,created_by BIGINT NOT NULL,created_at DATETIME(6) NOT NULL,CONSTRAINT fk_invoice_document FOREIGN KEY(invoice_id) REFERENCES invoices(id),CONSTRAINT fk_document_presentation FOREIGN KEY(presentation_id) REFERENCES invoice_presentations(id));
CREATE TABLE invoice_reminder_policy (id BIGINT NOT NULL PRIMARY KEY,enabled BOOLEAN NOT NULL DEFAULT FALSE,revision BIGINT NOT NULL,after_days INT NOT NULL,repeat_days INT NOT NULL,channel VARCHAR(30) NOT NULL,message VARCHAR(500) NOT NULL);
INSERT INTO invoice_reminder_policy(id,enabled,revision,after_days,repeat_days,channel,message) VALUES(1,FALSE,1,0,7,'MANUAL','');
CREATE TABLE invoice_reminder_tasks (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT NOT NULL,policy_revision BIGINT NOT NULL,scheduled_for DATE NOT NULL,channel VARCHAR(30) NOT NULL,message VARCHAR(500) NOT NULL,state VARCHAR(20) NOT NULL,outcome VARCHAR(500) NULL,handled_by BIGINT NULL,created_at DATETIME(6) NOT NULL,CONSTRAINT fk_reminder_task_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id),CONSTRAINT uk_invoice_reminder_slot UNIQUE(invoice_id,policy_revision,scheduled_for),INDEX idx_reminder_task_state(state,id));
CREATE TABLE invoice_reconciliations (id VARCHAR(36) NOT NULL PRIMARY KEY,customer_id VARCHAR(50) NOT NULL,currency VARCHAR(3) NOT NULL,fee_ids VARCHAR(600) NOT NULL,issue_date DATE NOT NULL,due_date DATE NOT NULL,tax DECIMAL(12,2) NULL,state VARCHAR(30) NOT NULL,invoice_id BIGINT NULL UNIQUE,error_status INT NULL,outcome VARCHAR(500) NULL,created_by BIGINT NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_reconciliation_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id),INDEX idx_reconciliation_created(created_at));
CREATE TABLE invoice_fee_claims (fee_id BIGINT NOT NULL PRIMARY KEY,job_id VARCHAR(36) NULL,invoice_id BIGINT NULL,line_id BIGINT NULL,CONSTRAINT fk_claim_job FOREIGN KEY(job_id) REFERENCES invoice_reconciliations(id),CONSTRAINT fk_claim_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id),CONSTRAINT fk_claim_line FOREIGN KEY(line_id) REFERENCES invoice_lines(id),INDEX idx_claim_job(job_id));
ALTER TABLE invoices ADD CONSTRAINT fk_invoice_reconciliation FOREIGN KEY(reconciliation_id) REFERENCES invoice_reconciliations(id);
-- fee_id and source-time references belong to Fees: deliberately no cross-database foreign key.
